#!/usr/bin/env python3
"""Kode v0.3: adds the tests, benchmarks, docs and small text files.

Run it from the root of your Kode repository (the folder with Cargo.toml), AFTER copying the
Rust files (crates/ and Cargo.toml) over your project:

    python3 kode-v0.3-add-files.py

It writes 48 files and removes 3 obsolete ones. It touches nothing else.
"""
import os
import sys

DELETE = ['benchmarks/fib/fib.kode', 'benchmarks/fib/fib.py', 'benchmarks/fib/run.sh']

FILES = {'.github/workflows/release.yml': 'name: release\non:\n  push:\n    tags: ["v*"]\njobs:\n  build:\n    strategy:\n      matrix:\n        os: [ubuntu-latest, macos-latest]\n    runs-on: ${{ matrix.os }}\n    steps:\n      - uses: actions/checkout@v4\n      - uses: dtolnay/rust-toolchain@stable\n      - run: cargo build --release -p kode\n      - run: tar -czf kode-${{ matrix.os }}.tar.gz -C target/release kode\n      - uses: softprops/action-gh-release@v2\n        with:\n          files: kode-${{ matrix.os }}.tar.gz\n', 'benchmarks/bench.py': '#!/usr/bin/env python3\n"""Kode benchmark harness.\n\n    python3 benchmarks/bench.py                 # every benchmark, every language found\n    python3 benchmarks/bench.py fib sieve       # only these benchmarks\n    python3 benchmarks/bench.py --runs 5 --langs kode,c,go\n\nEach benchmark is a folder with main.kode, main.c, main.go, main.js, main.py\n(add your own!) and an `expected.txt` with the right answer. A language whose tool\nis not installed is skipped. Memory is the real peak resident size of each run.\n"""\nimport argparse, os, platform, shutil, statistics, subprocess, sys, tempfile, time\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nROOT = os.path.dirname(HERE)\n\n\ndef find_kode():\n    for c in [os.environ.get("KODE"), os.path.join(ROOT, "target/release/kode"),\n              os.path.join(ROOT, "target/debug/kode"), shutil.which("kode")]:\n        if c and os.path.exists(c):\n            return c\n    return None\n\n\nKODE = find_kode()\n\n# language -> (source file, tool to look for, build command or None, run command)\ndef langs(src, out):\n    return {\n        "kode":       ("main.kode", KODE, [KODE, "build", src, "-o", out, "--release"] if KODE else None, [out]),\n        "c":          ("main.c", "gcc", ["gcc", "-O2", "-ffp-contract=off", "-o", out, src, "-lm"], [out]),\n        "cpp":        ("main.c", "g++", ["g++", "-O2", "-ffp-contract=off", "-x", "c++", "-o", out, src, "-lm"], [out]),\n        "go":         ("main.go", "go", ["go", "build", "-o", out, src], [out]),\n        "javascript": ("main.js", "node", None, ["node", src]),\n        "python":     ("main.py", "python3", None, ["python3", src]),\n    }\n\n\ndef run_once(cmd, timeout):\n    """Run a command; return (seconds, peak_rss_bytes, stdout, ok)."""\n    with tempfile.TemporaryFile() as out:\n        t0 = time.perf_counter()\n        p = subprocess.Popen(cmd, stdout=out, stderr=subprocess.DEVNULL)\n        peak = 0\n        while True:\n            if sys.platform.startswith("linux"):\n                try:  # peak resident size of the running program itself\n                    for line in open(f"/proc/{p.pid}/status"):\n                        if line.startswith("VmHWM:"):\n                            peak = max(peak, int(line.split()[1]) * 1024)\n                except OSError:\n                    pass\n            done, status, ru = os.wait4(p.pid, os.WNOHANG)\n            if done:\n                break\n            if time.perf_counter() - t0 > timeout:\n                p.kill(); os.wait4(p.pid, 0)\n                return None, 0, "", False\n            time.sleep(0.002)\n        secs = time.perf_counter() - t0\n        out.seek(0)\n        text = out.read().decode(errors="replace").strip()\n    # Linux: sampled from /proc. macOS: the kernel\'s number (it includes a few MB from the harness).\n    rss = peak or ru.ru_maxrss * (1 if platform.system() == "Darwin" else 1024)\n    return secs, rss, text, os.WIFEXITED(status) and os.WEXITSTATUS(status) == 0\n\n\ndef fmt_bytes(n):\n    return f"{n/1048576:.1f} MB" if n else "n/a"\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("names", nargs="*")\n    ap.add_argument("--runs", type=int, default=3)\n    ap.add_argument("--langs", default="")\n    ap.add_argument("--timeout", type=float, default=120)\n    a = ap.parse_args()\n    names = a.names or sorted(d for d in os.listdir(HERE) if os.path.isfile(os.path.join(HERE, d, "expected.txt")))\n    wanted = [x for x in a.langs.split(",") if x]\n    report = ["# Kode benchmark results", "", f"Machine: {platform.platform()}, {os.cpu_count()} CPU(s). Median of {a.runs} runs.", ""]\n    for name in names:\n        d = os.path.join(HERE, name)\n        expected = open(os.path.join(d, "expected.txt")).read().strip()\n        print(f"\\n== {name} (expected {expected})")\n        report += [f"## {name}", "", "| Language | Median | Min | Max | Peak memory | Result |", "|---|---|---|---|---|---|"]\n        tmp = tempfile.mkdtemp(prefix="kodebench-")\n        results = []\n        for lang in ["kode", "c", "cpp", "go", "javascript", "python"]:\n            if wanted and lang not in wanted:\n                continue\n            src_name, tool, build, run = langs("", "")[lang]\n            src = os.path.join(d, src_name)\n            if not os.path.exists(src):\n                continue\n            out = os.path.join(tmp, lang)\n            _, tool, build, run = langs(src, out)[lang]\n            if not tool or not shutil.which(tool) and not os.path.exists(str(tool)):\n                print(f"{lang:11} SKIPPED (not installed)"); report.append(f"| {lang} | skipped | | | | not installed |"); continue\n            if build:\n                b = subprocess.run(build, capture_output=True, text=True)\n                if b.returncode != 0:\n                    print(f"{lang:11} BUILD FAILED: {b.stderr.strip()[:200]}"); report.append(f"| {lang} | build failed | | | | |"); continue\n            times, rss, ok = [], 0, True\n            for _ in range(a.runs):\n                secs, r, text, good = run_once(run, a.timeout)\n                if secs is None:\n                    ok = False; text = "timeout"; break\n                if not good or text != expected:\n                    ok = False; text = text[:40]; break\n                times.append(secs); rss = max(rss, r)\n            if not ok:\n                print(f"{lang:11} WRONG ({text})"); report.append(f"| {lang} | wrong | | | | {text} |"); continue\n            med = statistics.median(times)\n            results.append((med, lang))\n            print(f"{lang:11} median {med:7.3f}s  min {min(times):7.3f}s  max {max(times):7.3f}s  memory {fmt_bytes(rss)}")\n            report.append(f"| {lang} | {med:.3f} s | {min(times):.3f} s | {max(times):.3f} s | {fmt_bytes(rss)} | ok |")\n        shutil.rmtree(tmp, ignore_errors=True)\n        report.append("")\n        if results:\n            results.sort()\n            report.append("Ranking: " + " < ".join(f"{l} ({t:.3f})" for t, l in results))\n            report.append("")\n    with open(os.path.join(HERE, "report.md"), "w") as f:\n        f.write("\\n".join(report) + "\\n")\n    print("\\nwrote benchmarks/report.md")\n\n\nmain()\n', 'benchmarks/collatz/expected.txt': '1117065\n', 'benchmarks/collatz/main.c': '#include <stdio.h>\nint main(void) {\n    long long best = 0, best_steps = 0;\n    for (long long n = 1; n < 1500000; n++) {\n        long long x = n, steps = 0;\n        while (x != 1) {\n            if (x % 2 == 0) x = x / 2; else x = 3 * x + 1;\n            steps++;\n        }\n        if (steps > best_steps) { best_steps = steps; best = n; }\n    }\n    printf("%lld\\n", best);\n    return 0;\n}\n', 'benchmarks/collatz/main.go': 'package main\n\nimport "fmt"\n\nfunc main() {\n\tvar best, bestSteps int64\n\tfor n := int64(1); n < 1500000; n++ {\n\t\tx, steps := n, int64(0)\n\t\tfor x != 1 {\n\t\t\tif x%2 == 0 {\n\t\t\t\tx = x / 2\n\t\t\t} else {\n\t\t\t\tx = 3*x + 1\n\t\t\t}\n\t\t\tsteps++\n\t\t}\n\t\tif steps > bestSteps {\n\t\t\tbestSteps = steps\n\t\t\tbest = n\n\t\t}\n\t}\n\tfmt.Println(best)\n}\n', 'benchmarks/collatz/main.js': 'let best = 0, bestSteps = 0;\nfor (let n = 1; n < 1500000; n++) {\n  let x = n, steps = 0;\n  while (x !== 1) {\n    if (x % 2 === 0) x = x / 2; else x = 3 * x + 1;\n    steps++;\n  }\n  if (steps > bestSteps) { bestSteps = steps; best = n; }\n}\nconsole.log(best);\n', 'benchmarks/collatz/main.kode': 'best = 0\nbest_steps = 0\nfor n in 1..1500000 {\n    x = n\n    steps = 0\n    while x != 1 {\n        if x % 2 == 0 {\n            x = x / 2\n        } else {\n            x = 3 * x + 1\n        }\n        steps += 1\n    }\n    if steps > best_steps {\n        best_steps = steps\n        best = n\n    }\n}\nprint(best)\n', 'benchmarks/collatz/main.py': 'best = 0\nbest_steps = 0\nfor n in range(1, 1500000):\n    x = n\n    steps = 0\n    while x != 1:\n        if x % 2 == 0:\n            x = x // 2\n        else:\n            x = 3 * x + 1\n        steps += 1\n    if steps > best_steps:\n        best_steps = steps\n        best = n\nprint(best)\n', 'benchmarks/fib/expected.txt': '39088169\n', 'benchmarks/fib/main.c': '#include <stdio.h>\nlong long fib(long long n) { return n < 2 ? n : fib(n - 1) + fib(n - 2); }\nint main(void) { printf("%lld\\n", fib(38)); return 0; }\n', 'benchmarks/fib/main.go': 'package main\n\nimport "fmt"\n\nfunc fib(n int64) int64 {\n\tif n < 2 {\n\t\treturn n\n\t}\n\treturn fib(n-1) + fib(n-2)\n}\n\nfunc main() { fmt.Println(fib(38)) }\n', 'benchmarks/fib/main.js': 'function fib(n) { return n < 2 ? n : fib(n - 1) + fib(n - 2); }\nconsole.log(fib(38));\n', 'benchmarks/fib/main.kode': 'fn fib(n: int) -> int {\n    if n < 2 {\n        return n\n    }\n    return fib(n - 1) + fib(n - 2)\n}\n\nprint(fib(38))\n', 'benchmarks/fib/main.py': 'def fib(n):\n    return n if n < 2 else fib(n - 1) + fib(n - 2)\n\nprint(fib(38))\n', 'benchmarks/loop_mod/expected.txt': '24975000000\n', 'benchmarks/loop_mod/main.c': '#include <stdio.h>\nint main(void) {\n    long long total = 0;\n    for (long long i = 0; i < 50000000; i++) total += (i * 7 + 3) % 1000;\n    printf("%lld\\n", total);\n    return 0;\n}\n', 'benchmarks/loop_mod/main.go': 'package main\n\nimport "fmt"\n\nfunc main() {\n\tvar total int64 = 0\n\tfor i := int64(0); i < 50000000; i++ {\n\t\ttotal += (i*7 + 3) % 1000\n\t}\n\tfmt.Println(total)\n}\n', 'benchmarks/loop_mod/main.js': 'let total = 0;\nfor (let i = 0; i < 50000000; i++) total += (i * 7 + 3) % 1000;\nconsole.log(total);\n', 'benchmarks/loop_mod/main.kode': 'total = 0\nfor i in 0..50000000 {\n    total += (i * 7 + 3) % 1000\n}\nprint(total)\n', 'benchmarks/loop_mod/main.py': 'total = 0\nfor i in range(50000000):\n    total += (i * 7 + 3) % 1000\nprint(total)\n', 'benchmarks/mandel/expected.txt': '6292386\n', 'benchmarks/mandel/main.c': '#include <stdio.h>\nint main(void) {\n    long long count = 0;\n    for (int py = 0; py < 300; py++)\n        for (int px = 0; px < 300; px++) {\n            double x0 = (double)px / 300.0 * 3.5 - 2.5;\n            double y0 = (double)py / 300.0 * 2.0 - 1.0;\n            double x = 0.0, y = 0.0;\n            int i = 0;\n            while (x * x + y * y <= 4.0 && i < 300) {\n                double xt = x * x - y * y + x0;\n                y = 2.0 * x * y + y0;\n                x = xt;\n                i++;\n            }\n            count += i;\n        }\n    printf("%lld\\n", count);\n    return 0;\n}\n', 'benchmarks/mandel/main.go': 'package main\n\nimport "fmt"\n\nfunc main() {\n\tvar count int64 = 0\n\tfor py := 0; py < 300; py++ {\n\t\tfor px := 0; px < 300; px++ {\n\t\t\tx0 := float64(float64(px)/300.0*3.5) - 2.5\n\t\t\ty0 := float64(float64(py)/300.0*2.0) - 1.0\n\t\t\tx, y := 0.0, 0.0\n\t\t\ti := 0\n\t\t\tfor float64(x*x)+float64(y*y) <= 4.0 && i < 300 {\n\t\t\t\txt := float64(float64(x*x)-float64(y*y)) + x0\n\t\t\t\ty = float64(float64(2.0*x)*y) + y0\n\t\t\t\tx = xt\n\t\t\t\ti++\n\t\t\t}\n\t\t\tcount += int64(i)\n\t\t}\n\t}\n\tfmt.Println(count)\n}\n', 'benchmarks/mandel/main.js': 'let count = 0;\nfor (let py = 0; py < 300; py++)\n  for (let px = 0; px < 300; px++) {\n    const x0 = px / 300.0 * 3.5 - 2.5;\n    const y0 = py / 300.0 * 2.0 - 1.0;\n    let x = 0.0, y = 0.0, i = 0;\n    while (x * x + y * y <= 4.0 && i < 300) {\n      const xt = x * x - y * y + x0;\n      y = 2.0 * x * y + y0;\n      x = xt;\n      i++;\n    }\n    count += i;\n  }\nconsole.log(count);\n', 'benchmarks/mandel/main.kode': 'count = 0\nfor py in 0..300 {\n    for px in 0..300 {\n        x0 = float(px) / 300.0 * 3.5 - 2.5\n        y0 = float(py) / 300.0 * 2.0 - 1.0\n        x = 0.0\n        y = 0.0\n        i = 0\n        while x * x + y * y <= 4.0 and i < 300 {\n            xt = x * x - y * y + x0\n            y = 2.0 * x * y + y0\n            x = xt\n            i += 1\n        }\n        count += i\n    }\n}\nprint(count)\n', 'benchmarks/mandel/main.py': 'count = 0\nfor py in range(300):\n    for px in range(300):\n        x0 = px / 300.0 * 3.5 - 2.5\n        y0 = py / 300.0 * 2.0 - 1.0\n        x = 0.0\n        y = 0.0\n        i = 0\n        while x * x + y * y <= 4.0 and i < 300:\n            xt = x * x - y * y + x0\n            y = 2.0 * x * y + y0\n            x = xt\n            i += 1\n        count += i\nprint(count)\n', 'benchmarks/report.md': '# Kode benchmark results\n\nMachine: Linux-6.18.44-fc-v185-x86_64-with-glibc2.39, 1 CPU(s). Median of 7 runs.\n\n## collatz\n\n| Language | Median | Min | Max | Peak memory | Result |\n|---|---|---|---|---|---|\n| kode | 0.476 s | 0.450 s | 0.537 s | 1.4 MB | ok |\n| c | 0.411 s | 0.382 s | 0.522 s | 1.2 MB | ok |\n| cpp | 0.390 s | 0.371 s | 0.470 s | 1.5 MB | ok |\n| go | 0.446 s | 0.422 s | 0.502 s | 1.6 MB | ok |\n| javascript | 2.779 s | 2.546 s | 3.092 s | 46.8 MB | ok |\n\nRanking: cpp (0.390) < c (0.411) < go (0.446) < kode (0.476) < javascript (2.779)\n\n## fib\n\n| Language | Median | Min | Max | Peak memory | Result |\n|---|---|---|---|---|---|\n| kode | 0.191 s | 0.189 s | 0.283 s | 1.5 MB | ok |\n| c | 0.089 s | 0.084 s | 0.140 s | 1.2 MB | ok |\n| cpp | 0.089 s | 0.081 s | 0.187 s | 1.2 MB | ok |\n| go | 0.249 s | 0.236 s | 0.294 s | 1.6 MB | ok |\n| javascript | 0.627 s | 0.487 s | 0.801 s | 46.4 MB | ok |\n\nRanking: cpp (0.089) < c (0.089) < kode (0.191) < go (0.249) < javascript (0.627)\n\n## loop_mod\n\n| Language | Median | Min | Max | Peak memory | Result |\n|---|---|---|---|---|---|\n| kode | 0.113 s | 0.078 s | 0.121 s | 1.4 MB | ok |\n| c | 0.059 s | 0.056 s | 0.087 s | 1.5 MB | ok |\n| cpp | 0.061 s | 0.056 s | 0.085 s | 1.6 MB | ok |\n| go | 0.106 s | 0.092 s | 0.180 s | 1.6 MB | ok |\n| javascript | 0.200 s | 0.149 s | 0.317 s | 47.8 MB | ok |\n\nRanking: c (0.059) < cpp (0.061) < go (0.106) < kode (0.113) < javascript (0.200)\n\n## mandel\n\n| Language | Median | Min | Max | Peak memory | Result |\n|---|---|---|---|---|---|\n| kode | 0.034 s | 0.029 s | 0.036 s | 1.4 MB | ok |\n| c | 0.034 s | 0.033 s | 0.036 s | 1.2 MB | ok |\n| cpp | 0.030 s | 0.030 s | 0.042 s | 1.2 MB | ok |\n| go | 0.035 s | 0.033 s | 0.046 s | 1.6 MB | ok |\n| javascript | 0.076 s | 0.067 s | 0.091 s | 48.7 MB | ok |\n\nRanking: cpp (0.030) < kode (0.034) < c (0.034) < go (0.035) < javascript (0.076)\n\n## sieve\n\n| Language | Median | Min | Max | Peak memory | Result |\n|---|---|---|---|---|---|\n| kode | 0.108 s | 0.091 s | 0.122 s | 11.3 MB | ok |\n| c | 0.058 s | 0.049 s | 0.063 s | 11.0 MB | ok |\n| cpp | 0.057 s | 0.054 s | 0.084 s | 10.8 MB | ok |\n| go | 0.105 s | 0.089 s | 0.118 s | 27.8 MB | ok |\n| javascript | 0.858 s | 0.796 s | 1.045 s | 344.4 MB | ok |\n\nRanking: cpp (0.057) < c (0.058) < go (0.105) < kode (0.108) < javascript (0.858)\n\n', 'benchmarks/sieve/expected.txt': '664579\n', 'benchmarks/sieve/main.c': '#include <stdio.h>\n#include <stdlib.h>\nint main(void) {\n    long long n = 10000000;\n    char *f = (char *)malloc(n + 1);\n    for (long long i = 0; i <= n; i++) f[i] = 1;\n    f[0] = 0; f[1] = 0;\n    for (long long i = 2; i * i <= n; i++)\n        if (f[i]) for (long long j = i * i; j <= n; j += i) f[j] = 0;\n    long long count = 0;\n    for (long long k = 0; k <= n; k++) if (f[k]) count++;\n    printf("%lld\\n", count);\n    return 0;\n}\n', 'benchmarks/sieve/main.go': 'package main\n\nimport "fmt"\n\nfunc main() {\n\tn := 10000000\n\tf := make([]bool, 0)\n\tfor i := 0; i <= n; i++ {\n\t\tf = append(f, true)\n\t}\n\tf[0] = false\n\tf[1] = false\n\tfor i := 2; i*i <= n; i++ {\n\t\tif f[i] {\n\t\t\tfor j := i * i; j <= n; j += i {\n\t\t\t\tf[j] = false\n\t\t\t}\n\t\t}\n\t}\n\tcount := 0\n\tfor k := 0; k <= n; k++ {\n\t\tif f[k] {\n\t\t\tcount++\n\t\t}\n\t}\n\tfmt.Println(count)\n}\n', 'benchmarks/sieve/main.js': 'const n = 10000000;\nconst f = [];\nfor (let i = 0; i <= n; i++) f.push(true);\nf[0] = false; f[1] = false;\nfor (let i = 2; i * i <= n; i++) {\n  if (f[i]) for (let j = i * i; j <= n; j += i) f[j] = false;\n}\nlet count = 0;\nfor (let k = 0; k <= n; k++) if (f[k]) count++;\nconsole.log(count);\n', 'benchmarks/sieve/main.kode': 'n = 10000000\nflags: [bool] = []\nfor i in 0..n + 1 {\n    flags.add(true)\n}\nflags[0] = false\nflags[1] = false\ni = 2\nwhile i * i <= n {\n    if flags[i] {\n        j = i * i\n        while j <= n {\n            flags[j] = false\n            j += i\n        }\n    }\n    i += 1\n}\ncount = 0\nfor k in 0..n + 1 {\n    if flags[k] {\n        count += 1\n    }\n}\nprint(count)\n', 'benchmarks/sieve/main.py': 'n = 10000000\nf = []\nfor i in range(n + 1):\n    f.append(True)\nf[0] = False\nf[1] = False\ni = 2\nwhile i * i <= n:\n    if f[i]:\n        j = i * i\n        while j <= n:\n            f[j] = False\n            j += i\n    i += 1\ncount = 0\nfor k in range(n + 1):\n    if f[k]:\n        count += 1\nprint(count)\n', 'docs/spec/12-tasks.md': "# 12. Tasks (concurrency)\n\n```\nfn work(n: int) -> int {\n    total = 0\n    for i in 0..n { total += i }\n    return total\n}\n\nt = spawn work(1000)            # starts a task on its own thread, gives a Task<int>\nprint(await t)                  # waits and gives the result\n\ntasks: [Task<int>] = []\nfor i in 1..=4 { tasks.add(spawn work(i * 10)) }\nsum = 0\nfor t in tasks { sum += await t }\n\nr = await spawn fails() catch e { -1 }     # an error inside a task is raised by `await`\n```\n\n- `spawn f(args)` needs one of your functions. Its parameters can only be `int`, `float`, `bool`\n  and `string` (E0230): tasks share nothing, so there are no data races. The result can be any type.\n- `await` waits for the result (E0231 if the value is not a task). It can raise the task's error,\n  so a function that uses `await` can fail like a function that uses `throw`.\n- A task that is never awaited is waited for and freed when its handle goes away.\n- Reference counts become atomic when the first task starts; programs without tasks pay nothing.\n- `sleep(ms)` pauses, `now_ms()` reads a steady clock in milliseconds (differences only).\n- Not yet: channels, shared classes, a thread pool (every task is a thread).\n", 'docs/spec/13-stdlib.md': '# 13. Standard library (v0.3)\n\nAll of these are runtime functions listed in one table (`crates/kode-sema/src/std_fns.rs`).\nAdding one means one table row and one `extern "C"` function in `crates/kode-rt/src/std_fns.rs`.\n\n| Strings | |\n|---|---|\n| `s.size()` | bytes (`len(s)` counts characters) |\n| `s.byte_at(i)` | byte at position `i` |\n| `s.slice(a, b)` | bytes `a` to `b` (error if not on a character boundary) |\n| `s.contains(t)` `s.starts_with(t)` `s.ends_with(t)` | bool |\n| `s.find(t)` | position or -1 |\n| `s.upper()` `s.lower()` `s.trim()` | new string |\n| `s.replace(a, b)` `s.repeat(n)` | new string |\n| `s.split(sep)` | `[string]` |\n| `s.to_int()` `s.to_float()` | raise an error if the text is not a number |\n| `chr(n)` | the character with that code |\n\n| Lists and maps | |\n|---|---|\n| `xs.sort()` | for `[int]`, `[float]`, `[string]` |\n| `xs.pop()` `xs.clear()` | not for `[bool]` |\n| `words.join(sep)` | for `[string]` |\n| `m.remove(key)` | |\n\n| Files, program, time | |\n|---|---|\n| `read_file(path)` `write_file(path, text)` | raise an error on failure |\n| `args()` | program arguments: `kode run app.kode -- a b` gives `["a", "b"]` |\n| `env(name)` | `string?` |\n| `exit(code)` | |\n| `sleep(ms)` `now_ms()` | |\n\n## Web server\n\n```\nfn handle(method: string, path: string, body: string) -> string {\n    if path == "/hello" { return "Hello from Kode" }\n    throw Error(message: "not found", code: 404)\n}\n\nserve(8080, handle)\n```\n\n`serve(port, handler)` runs an HTTP/1.1 server with keep-alive on a pool of threads. The handler\nreceives the method, the path (with the query) and the body, and returns the response text\n(JSON is detected when it starts with `{` or `[`). An error with a `code` from 400 to 599 becomes\nthat status; any other error is a 500. Try it: `kode run tests/http/server.kode -- 8080`\nand `curl localhost:8080/hello`.\n\nNot yet: a JSON parser, an HTTP client, TLS, a database client.\n', 'tests/http/server.kode': 'fn handle(method: string, path: string, body: string) -> string {\n    if path == "/hello" {\n        return "Hello from Kode"\n    }\n    if path.starts_with("/echo/") {\n        return path.slice(6, path.size())\n    }\n    if path == "/json" {\n        return "{\\"ok\\": true}"\n    }\n    if method == "POST" and path == "/size" {\n        return string(body.size())\n    }\n    throw Error(message: "not found", code: 404)\n}\n\nserve(args()[0].to_int(), handle)\n', 'tests/run-pass/file_io.kode': 'write_file("/tmp/kode_io_test.txt", "line1\\nline2\\n")\ntext = read_file("/tmp/kode_io_test.txt")\nlines = text.trim().split("\\n")\nprint(len(lines), lines[1])\nmissing = read_file("/tmp/definitely/not/here.txt") catch e {\n    print("read failed")\n    ""\n}\nprint(missing.size())\nt0 = now_ms()\nsleep(20)\nprint(now_ms() - t0 >= 15)\nprint(env("KODE_SURELY_NOT_SET") ?? "unset")\nprint(len(args()))\n', 'tests/run-pass/file_io.out': '2 line2\nread failed\n0\ntrue\nunset\n0\n', 'tests/run-pass/strings_std.kode': 's = "Hello, World"\nprint(s.size(), s.upper(), s.lower(), s.contains("World"), s.starts_with("He"), s.ends_with("x"))\nprint(s.find("World"), s.find("zzz"), s.slice(0, 5), s.replace("l", "L"))\nwords = "a,b,,c".split(",")\nprint(len(words), words.join("|"))\nprint("  padded ".trim() + "!", "ab".repeat(3))\nprint("42".to_int() + 1, "2.5".to_float() * 2.0, chr(65) + chr(97))\nbad = "x1".to_int() catch e {\n    print(e.message)\n    -1\n}\nprint(bad)\nprint(s.byte_at(0))\nnums = [5, 2, 9, 1]\nnums.sort()\nprint(nums[0], nums[3], nums.pop(), len(nums))\nnames = ["zed", "amy", "bob"]\nnames.sort()\nprint(names.join(","))\nfs = [2.5, 1.5]\nfs.sort()\nprint(fs[0], fs.pop())\nnums.clear()\nprint(len(nums))\nm = {"a": 1, "b": 2, "c": 3}\nm.remove("b")\nprint(len(m), "b" in m, m.keys().join(""))\n', 'tests/run-pass/strings_std.out': '12 HELLO, WORLD hello, world true true false\n7 -1 Hello HeLLo, WorLd\n4 a|b||c\npadded! ababab\n43 5.0 Aa\nnot an int: "x1"\n-1\n72\n1 9 9 3\namy,bob,zed\n1.5 2.5\n0\n2 false ac\n', 'tests/run-pass/tasks.kode': 'fn work(n: int) -> int {\n    total = 0\n    for i in 0..n {\n        total += i\n    }\n    return total\n}\n\nfn greet(name: string) -> string {\n    return "hi " + name + "!"\n}\n\nfn half(x: float) -> float => x / 2.0\n\nfn is_big(n: int) -> bool => n > 10\n\nfn tick() {\n}\n\nfn fails() -> int {\n    throw "boom"\n}\n\nt1 = spawn work(100)\nt2 = spawn work(1000)\nprint(await t1, await t2)\n\ntasks: [Task<int>] = []\nfor i in 1..=4 {\n    tasks.add(spawn work(i * 10))\n}\nsum = 0\nfor t in tasks {\n    sum += await t\n}\nprint(sum)\n\ns = spawn greet("Asha")\nprint(await s)\nprint(await spawn half(5.0), await spawn is_big(50))\n\nt = spawn tick()\nawait t\n\nboom = spawn fails()\nr = await boom catch e {\n    print("task failed:", e.message)\n    -1\n}\nprint(r)\n\nunused = spawn work(10)\nprint("done")\n', 'tests/run-pass/tasks.out': '4950 499500\n1450\nhi Asha!\n2.5 true\ntask failed: boom\n-1\ndone\n', 'CHANGELOG.md': '# Changelog\n\n## 0.3.0 (M6, M7, performance)\n- Tasks: `spawn f(args)`, `await t`, type `Task<T>`; atomic reference counts when threads exist; one error slot per thread.\n- Standard library table: string, list, map, file, environment, time functions (see docs/spec/13-stdlib.md).\n- `serve(port, handler)`: HTTP/1.1 server with keep-alive on a thread pool.\n- The runtime library is embedded in the compiler (no stale runtime, `kode` works from any folder).\n- `kode run file.kode -- args`; optimization is on by default (`--debug` turns it off).\n- Faster code: constant division without checks, `x % 2 == 0` as a bit test, inlined list access and `add`,\n  1-byte `[bool]` lists, loop rotation, conditions that branch directly, `if/else` to `select`, a small-function\n  inliner, no frame pointers.\n- Benchmark suite and harness in `benchmarks/` (Kode, C, C++, Go, JavaScript, Python; real peak memory).\n\n## 0.2.0 (M2 to M5)\n- Lists `[T]` and maps `{string: T}`: literals, indexing, `.add`, `.len`, `in`, `.keys`, `for x in list`, `for k, v in map`.\n- Classes with fields, defaults, methods and named constructor arguments; enums; `match`.\n- Optionals `T?` for heap types with `none`, `?.`, `??`, `!`.\n- Errors: `throw`, `try / catch`, `expr catch e { ... }`, built-in `Error` class, errors that are freed on every path.\n- Named arguments for every call.\n- Imports across files (`import`, `from ... import`) with cycle and missing-file errors.\n- `test` blocks and `kode test`; `kode fmt`; `kode explain`; `kode mir` shows field loads and stores.\n- Runtime: one object header and one `release` for strings, lists, maps and objects; leak counter covers all of them.\n- MIR: single exit block per function, error edges that release live temporaries.\n- 19 run-pass programs (leak checked), 70 compile-fail programs, tests for `kode test`, `fmt`, `explain`.\n\n## 0.1.0 (first working core)\n- Rust rewrite: lexer, parser, type checker, MIR, Cranelift backend, runtime.\n- Types: int, float, bool, string. Block-scoped variables, constants.\n- Control flow: if / else if / else, while, for over ranges, break, continue.\n- Functions: parameters, return values, recursion, expression bodies.\n- Strings: reference counted, `+`, `${...}` interpolation, `len`, conversions.\n- Diagnostics with stable codes, "did you mean" hints and JSON output.\n- Conformance suite: 11 run-pass programs (leak checked) and 44 compile-fail programs.\n', 'README.md': '# Kode\n\n**A compiled language that is easy to write and cheap to run.**\nPython-readable, JavaScript-familiar, compiled to small native binaries,\nbuilt for cloud backends and for AI agents to write.\n\n```\nfn fib(n: int) -> int {\n    if n < 2 {\n        return n\n    }\n    return fib(n - 1) + fib(n - 2)\n}\n\nname = "Asha"\nprint("${name}: fib(30) =", fib(30))\n```\n\nKode is written in Rust. The compiler turns source into a native program:\n\n```\nsource -> lexer -> parser -> AST -> type check -> MIR -> Cranelift -> object file -> linker -> binary\n```\n\n## Status: v0.3 (working)\n\nWorks today: `int`, `float`, `bool`, `string`; variables and constants; operators; `if`, `while`,\n`for` over ranges, lists and maps, `break`, `continue`, `match`; functions with recursion and named\narguments; **lists** `[T]` and **maps** `{string: T}`; **classes** with methods and defaults;\n**enums**; **optionals** `T?` with `?.`, `??`, `!`; **errors** with `throw`, `try / catch` and\n`expr catch e { ... }`; **imports** across files; `test` blocks; reference-counted memory with a leak\nchecker; errors with codes, hints and JSON output.\n\nTools: `kode run | build | check | test | fmt | explain | mir`.\n\n**Tasks** (`spawn` / `await`), a **web server** (`serve`), strings, files, arguments and sorting are in too.\nNext: JSON, an HTTP client, budgets and AI features (M8), then Windows, an LLVM backend and a language server (M9).\nSee [docs/ROADMAP.md](docs/ROADMAP.md) and the one-page [cheat sheet](docs/agents/cheatsheet.md).\n\nMeasured on one dev machine (recursive Fibonacci of 35): Kode about 0.06 s, Python about 0.9 to 1.8 s,\nrelease binary about 330 KB. Treat this as a first data point, not a claim. See `benchmarks/`.\n\n## Build and run\n\nNeeds Rust 1.91 or newer and a C compiler (`cc`). On a Mac: `xcode-select --install`.\n\n```\ncargo build --workspace\ncargo test --workspace\n./target/debug/kode run examples/hello.kode\n```\n\nTo type just `kode` in this terminal:\n\n```\nexport PATH="$PWD/target/debug:$PATH"\nkode run examples/tour.kode\n```\n\n## Commands\n\n| Command | What it does |\n|---|---|\n| `kode run file.kode` | compile and run |\n| `kode build file.kode [-o out] [--release]` | make a native binary |\n| `kode check file.kode` | errors only, no code generation |\n| `kode test [file or folder]` | run `test` blocks |\n| `kode fmt <files or folders> [--check]` | format source files |\n| `kode explain E0201` | explain an error code |\n| `kode tokens file.kode` | print tokens (debugging) |\n| `kode ast file.kode` | print the syntax tree (debugging) |\n| `kode mir file.kode` | print the MIR, including retain/release (debugging) |\n| `--format=json` | diagnostics as JSON, for editors and AI agents |\n| `--strict` | warnings count as errors |\n\n## Repository map\n\n```\ncrates/\n  kode-diagnostics/   spans and error messages (human + JSON)\n  kode-syntax/        tokens, lexer, AST, parser\n  kode-sema/          names and types\n  kode-mir/           mid-level IR, lowering, dump, verifier\n  kode-codegen/       MIR -> Cranelift -> object file -> linker\n  kode-rt/            runtime library linked into every program\n  kode-cli/           the `kode` command\ntests/run-pass/       programs that must run (.kode + .out), checked for leaks\ntests/compile-fail/   programs that must fail (.kode + .err with the error code)\nexamples/             small programs\nbenchmarks/           proof of the cost claims\ndocs/                 spec, design notes, decisions (ADRs), roadmap, error codes\n```\n\n## License\n\nMIT\n', 'docs/ROADMAP.md': '# Roadmap\n\nGoal: a language that serves more requests per cloud server than Java, Node and Python,\nis simple to write, and is easy for AI agents to use.\n\nTime budget assumption: under 10 hours a week, so each milestone is small and ends with a\nworking, tested compiler.\n\n| Milestone | Content | Status |\n|---|---|---|\n| **M1 Core** | int, float, bool, string; variables, const; operators; if, while, for ranges; functions and recursion; reference-counted strings; MIR; Cranelift; diagnostics with codes and JSON; conformance suite | **Done** |\n| **M2 Collections** | `[T]` lists and `{string: T}` maps, indexing, `for x in list`, `.add`, `.len()`, `in`, `.keys()` (sorting, `map` and `filter` still to come) | **Done** |\n| **M3 Classes** | `class` with fields and methods, named constructors, reference counting for objects, enums, `match` (`weak` fields still to come) | **Done** |\n| **M4 Errors and optionals** | `throw` / `catch` / `try`, `T?` for heap types, `none`, `?.`, `??`, `!` (`finally`, `int?` and narrowing still to come) | **Done** |\n| **M5 Tooling** | `import` and modules, `test` blocks and `kode test`, `kode fmt`, `kode explain`, agent cheat sheet (project file and qualified module names still to come) | **Done** |\n| **M6 Concurrency** | `spawn` / `await`, `Task<T>`, atomic reference counts, per-thread errors (channels and `shared` classes still to come) | **Done** |\n| **M7 Services** | `serve(port, handler)`, strings, files, args, environment, sorting (JSON, HTTP client, database client and the REST benchmark still to come) | **Done** (core) |\n| **M8 Budgets and AI** | `memory` budgets, declared effects (`uses`), typed `ask` / `tool` calls | Planned |\n| **M9 Release** | LLVM backend for `--release` (optional), Windows, language server, docs site, open source | Planned |\n\n## Checkpoints (go / no-go)\n\n- After M2: the same small program in Kode and Python, compared on speed and lines of code. (`examples/bank.kode` is the first candidate.)\n- After M7: the REST benchmark on a 1 vCPU / 1 GB VM. Kode must clearly beat Python and Node on\n  requests per second and RAM, and be close to Go. If not, change the plan before M8.\n\n## Principles\n\n1. The conformance suite is the source of truth for the language.\n2. One backend input: MIR.\n3. Every error has a code and a hint.\n4. Measure before claiming.\n', 'docs/agents/cheatsheet.md': '# Kode cheat sheet (v0.3)\n\nCompiled language, one statement per line, no semicolons. Types: `int float bool string`,\n`[T]` list, `{string: T}` map, `T?` optional (string, list, map, class), classes, enums.\n\n```\n// comment            /* block */\nx = 5                 // declares; type is fixed; block-scoped\ny: float = 2.5        // explicit type\nconst MAX = 100       // plain literal only\nx += 1                // also -= *= /= %=\ns = "Hi ${name}, ${x + 1}"        // interpolation; escapes \\n \\t \\" \\\\ \\$\na = [1, 2, 3]         a[0]   a.add(4)   a.len()   for x in a   for i, x in a\nm = {"k": 1}          m["k"] m["z"] = 2   "k" in m   m.has("k")   m.keys()   for k, v in m\n```\n\nOperators: `+ - * / %`  `== != < <= > >=`  `and or not`  `??`  `?.`  `!`  `in`.\n`int / int` truncates. Numbers never mix: use `int(x)`, `float(x)`. Conditions must be `bool`.\n\n```\nif a > b { ... } else if a == b { ... } else { ... }\nwhile cond { ... }          for i in 0..10 { ... }     for i in 0..=10 { ... }\nbreak   continue            match v { 1 => print("one")  _ => print("other") }\n\nfn add(a: int, b: int) -> int { return a + b }      // return type required when it returns a value\nfn sq(x: int) -> int => x * x                        // one-expression body\nfn greet(name: string) { print("hi", name) }         // returns nothing\ngreet(name: "Asha")                                  // named arguments\n\nclass Account {\n    owner: string\n    balance: int = 0\n    fn deposit(n: int) { balance += n }              // fields by plain name\n}\nacct = Account(owner: "Asha")   acct.deposit(5)   acct.balance\n\nenum Color { Red, Green }       c = Color.Red        // compare with ==, use with match\n\nu: Account? = none     u?.owner ?? "nobody"    u!.owner\nthrow "message"        throw Error(message: "x", code: 7)\nv = f() catch e { print(e.message)  -1 }            // last line is the value\ntry { f() } catch e { print(e.message) }\n\nimport "./util"        from "./util" import helper   // modules share one namespace\ntest "name" { assert(1 + 1 == 2) }                   // run with: kode test\n```\n\nTasks: `t = spawn work(1, "a")` (int/float/bool/string args)   `r = await t`   `Task<int>`\nLibrary: `s.size() s.slice(a,b) s.split(",") s.find(t) s.upper() s.trim() s.to_int()`  `xs.sort() xs.pop()`  `words.join(",")`\n`read_file(p) write_file(p,t) args() env(n) exit(c) sleep(ms) now_ms() chr(n)`   `serve(8080, handler)`\n\nBuilt-ins: `print(...)`, `len(x)`, `int(x)`, `float(x)`, `string(x)`, `assert(cond)`.\nCommands: `kode run|build|check|test|fmt|explain|mir`. Use `kode check --format=json` for errors\nand `kode explain E0201` for help. Strict rules: no implicit conversions, no truthy values, no\ninheritance, no semicolons, one statement per line.\n', 'docs/errors/index.md': '# Error codes\n\nEvery message has a stable code. `kode check --format=json` prints them as JSON, and\n`kode explain E0201` shows a longer explanation with an example. Each code has a test in\n`tests/compile-fail/`.\n\n## Lexer (E000x)\n\n| Code | Meaning |\n|---|---|\n| E0001 | string is never closed |\n| E0002 | unknown escape sequence |\n| E0003 | `${` is never closed |\n| E0004 | block comment is never closed |\n| E0005 | integer literal is too large |\n| E0006 | not a valid number |\n| E0007 | unexpected character (including `;`) |\n\n## Parser (E01xx)\n\n| Code | Meaning |\n|---|---|\n| E0101 | expected the end of the line |\n| E0102 | expected a value |\n| E0103 | expected a specific token such as `)` or `{` |\n| E0105 | function defined inside a block |\n| E0106 | block is never closed |\n| E0107 | expected `=` after a declared type |\n| E0108 | a range loop has exactly one variable |\n| E0110 | expected a name |\n| E0111 | missing or invalid type |\n| E0112 | this cannot be assigned to |\n| E0114 | expected a field or a method in a class |\n| E0115 | map keys must be strings |\n| E0116 | expected a quoted file path or name |\n| E0117 | `spawn` needs a function call |\n\n## Type checker (E02xx)\n\n| Code | Meaning |\n|---|---|\n| E0201 | unknown variable |\n| E0202 | wrong type in assignment or declaration |\n| E0203 | operator or function cannot be used with these types |\n| E0204 | division by zero (constant) |\n| E0205 | a call that returns nothing was used as a value |\n| E0206 | unknown function |\n| E0207 | wrong number of arguments |\n| E0208 | wrong argument type |\n| E0209 | condition is not a bool |\n| E0210 | int and float mixed without conversion |\n| E0211 | this value cannot be indexed |\n| E0212 | wrong index type (lists need an int, maps need a string) |\n| E0213 | list or map items have different types |\n| E0214 | cannot loop over this value |\n| E0215 | bad named argument |\n| E0216 | missing argument |\n| E0217 | unknown field or method |\n| E0218 | this value has no fields |\n| E0219 | optional type or `?.` not supported for this type |\n| E0220 | value may be none and cannot be used directly |\n| E0221 | `?.` or `??` used on something that is not an optional |\n| E0222 | an empty list or map needs a declared type |\n| E0223 | bad `match` value or pattern type |\n| E0224 | `match` does not cover every case |\n| E0225 | unknown enum variant |\n| E0226 | `throw` needs a string or an `Error` |\n| E0227 | `catch` block does not end with a value |\n| E0228 | parameter has the same name as a field |\n| E0230 | `spawn` needs one of your functions with int, float, bool or string parameters |\n| E0231 | `await` needs a task |\n| E0232 | the `serve` handler must be a function `(string, string, string) -> string` |\n\n## Declarations and statements (E03xx)\n\n| Code | Meaning |\n|---|---|\n| E0301 | function, class, enum or method defined twice |\n| E0302 | name is a built-in function |\n| E0303 | unknown type name |\n| E0304 | `=>` body does not match the declared type |\n| E0305 | not every path returns a value |\n| E0306 | parameter or field name used twice |\n| E0307 | constant is not a plain value |\n| E0308 | constant defined twice |\n| E0310 | `return` value has the wrong type |\n| E0311 | `return` outside a function |\n| E0312 | assignment to a constant |\n| E0313 | variable already declared |\n| E0314 | `break` or `continue` outside a loop |\n\n## Modules (E04xx)\n\n| Code | Meaning |\n|---|---|\n| E0401 | imported file not found |\n| E0402 | import cycle |\n| E0403 | a module has top-level code |\n| E0405 | the module does not define this name |\n\n## Warnings\n\n| Code | Meaning |\n|---|---|\n| W0001 | variable assigned but never used (`--strict` turns it into an error) |\n', 'docs/spec/07-planned.md': '# 7. Planned (not implemented yet)\n\n```\nservice Todos {                       # M8: services with budgets and effects\n    memory 64mb\n    get("/todos") uses db => todos\n}\n```\n\n- M6 and M7 are done (chapters 12 and 13). Still missing from them: channels, `shared` classes, JSON, an HTTP client, a database client.\n- M8: resource budgets (`memory 64mb`), declared effects (`uses db`), typed `ask` / `tool` calls for AI.\n- Later: `weak` references, interfaces, `finally`, `int?`, optional narrowing, integer map keys,\n  list sorting and `map`/`filter`, qualified module names, a package manager, a language server.\n'}


def main():
    if not os.path.exists("Cargo.toml"):
        sys.exit("Run this from the root of the Kode repository (the folder with Cargo.toml).")
    for path in DELETE:
        if os.path.exists(path):
            os.remove(path)
            print("removed", path)
    for path, text in FILES.items():
        os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
        with open(path, "w", encoding="utf-8", newline="\n") as f:
            f.write(text)
    print("wrote", len(FILES), "files")


main()